int age = 21;            /* declaration + init */
const double PI = 3.14159; /* read-only */
unsigned int count = 0u;
long long big = 9000000000LL;
char grade = 'A';         /* single quotes */

printf("%zu\n", sizeof(int));
printf("%zu\n", sizeof age);
#include <limits.h>
printf("%d %d\n", INT_MIN, INT_MAX);

double d = 3.99;
int i = (int)d;      /* explicit cast -> 3 */
int j = d;           /* implicit conversion, warning */
unsigned u = 0;
u--;                 /* wraps to UINT_MAX */

examples.code:
#include <stdio.h>

int main(void) {
    char c = 'A';
    int i = 42;
    float f = 3.5f;
    double d = 2.718281828;
    printf("%c %d %.1f %.3f\n", c, i, f, d);
    printf("sizes: %zu %zu %zu %zu\n", sizeof c, sizeof i, sizeof f, sizeof d);
    return 0;
}

#include <stdio.h>
#include <limits.h>

int main(void) {
    double price = 99.99;
    int rounded = (int)price;
    unsigned char small = 250;
    small += 10;
    printf("%d %u\n", rounded, (unsigned)small);
    printf("INT_MAX = %d\n", INT_MAX);
    return 0;
}

