#include <stdio.h>
#include <limits.h>

int main(void) {
    printf("char    %zu bytes  min=%d max=%d\n", sizeof(char), CHAR_MIN, CHAR_MAX);
    printf("int     %zu bytes  min=%d max=%d\n", sizeof(int), INT_MIN, INT_MAX);
    return 0;
}
